param([Parameter(Mandatory=$true)][string]$Directory,[Parameter(Mandatory=$true)][string]$Output)
$ErrorActionPreference='Stop'
function Read-Definitions([string]$File){$t=$null;$e=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($File,[ref]$t,[ref]$e);if($e.Count){throw 'Function proof parse failed'};return ,@($ast.FindAll({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst]},$true))}
function Get-TextFact([string]$Text){$b=[Text.Encoding]::UTF8.GetBytes($Text);$h=[Security.Cryptography.SHA256]::Create();try{$s=([BitConverter]::ToString($h.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};return [ordered]@{bytes=$b.Length;sha256=$s}}
$reference=Join-Path $Directory 'references/qualified57-wrapper.ps1';$wrapper=Join-Path $Directory 'run-segment-observer.ps1';$a=Read-Definitions $reference;$b=Read-Definitions $wrapper;$records=@();foreach($name in @('Test-ReferenceWitnessPostflightInteger','Test-ReferenceWitnessPostflightReady','Invoke-ReferenceWitnessPostflight')){$old=@($a|Where-Object Name -CEQ $name);$new=@($b|Where-Object Name -CEQ $name);if($old.Count -ne 1 -or $new.Count -ne 1 -or $old[0].Extent.Text -cne $new[0].Extent.Text){throw 'Qualified helper bytes differ'};$records+=@([ordered]@{name=$name;qualified=(Get-TextFact $old[0].Extent.Text);current=(Get-TextFact $new[0].Extent.Text);exact=$true})}
[ordered]@{qualifiedRevision='57acc14a61c19cceab26d5bce7b3ce6c6aa745c2';qualifiedWrapperSha256=(Get-FileHash -LiteralPath $reference -Algorithm SHA256).Hash.ToLowerInvariant();wrapperSha256=(Get-FileHash -LiteralPath $wrapper -Algorithm SHA256).Hash.ToLowerInvariant();helpers=$records;lineEndingNormalizationApplied=$false;officeInvoked=$false}|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $Output -Encoding UTF8
Write-Output 'PASS3 exact qualified helper definitions; no newline normalization or evaluation'
